import{_ as r,C as s,o as e,c as i,a2 as o,b as c,w as d,a as n,E as u,a3 as l}from"./chunks/framework.BaXgE4DV.js";const b=JSON.parse('{"title":"질문으로 쓰기","description":"","frontmatter":{},"headers":[],"relativePath":"features/guided-writing.md","filePath":"features/guided-writing.md","lastUpdated":1791389169000}'),E={name:"features/guided-writing.md"};function A(p,t,q,B,h,C){const a=s("Mermaid");return e(),i("div",null,[t[1]||(t[1]=o('<h1 id="guided-writing" tabindex="-1">질문으로 쓰기 <a class="header-anchor" href="#guided-writing" aria-label="Permalink to &quot;질문으로 쓰기 {#guided-writing}&quot;">​</a></h1><p>&quot;질문으로 쓰기&quot;는 무엇을 써야 할지 모를 때 질문에 답하며 감사 글을 시작하는 작성 모드입니다. 질문은 운영자가 선정한 질문(기본 질문 + 사용자가 제안해 선정된 질문)에서 고릅니다. 답변과 초안 만들기는 모두 <strong>기기 안에서</strong> 이루어지고, 작성 내용은 사용자가 저장할 때 일반 글 저장 경로로만 Firestore에 올라갑니다. → <a href="/grato-docs/decisions#adr-10">결정 기록 #10</a>, <a href="/grato-docs/decisions#adr-11">#11</a></p><h2 id="흐름" tabindex="-1">흐름 <a class="header-anchor" href="#흐름" aria-label="Permalink to &quot;흐름&quot;">​</a></h2>',3)),(e(),c(l,null,{default:d(()=>[u(a,{id:"mermaid-9",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20U%20as%20%EC%82%AC%EC%9A%A9%EC%9E%90%0A%20%20participant%20W%20as%20WritePage%20(GuidedMode)%0A%20%20participant%20A%20as%20src%2Flib%2FquestionApi.js%0A%20%20participant%20Q%20as%20src%2Fcontent%2Fquestions.js%0A%20%20participant%20F%20as%20Firestore%0A%20%20W-%3E%3EA%3A%20loadQuestionPools()%20(%EC%84%B8%EC%85%98%EC%97%90%20%ED%95%9C%20%EB%B2%88)%0A%20%20A-%3E%3EF%3A%20questions%20where%20status%20%3D%3D%20approved%2C%20limit%20500%0A%20%20F--%3E%3EA%3A%20%EC%84%A0%EC%A0%95%EB%90%9C%20%EC%A7%88%EB%AC%B8%0A%20%20A-%3E%3EQ%3A%20buildQuestionPools(%EC%84%A0%EC%A0%95%EB%90%9C%20%EC%A7%88%EB%AC%B8)%0A%20%20Q--%3E%3EW%3A%20%7B%20opening%2C%20followup%20%7D%0A%20%20W-%3E%3EQ%3A%20pickQuestion(opening)%0A%20%20U-%3E%3EW%3A%20%EB%8B%B5%EB%B3%80%201%0A%20%20W-%3E%3EQ%3A%20pickQuestion(followup)%0A%20%20alt%20%EB%8B%B5%EB%B3%80%ED%95%A8%0A%20%20%20%20U-%3E%3EW%3A%20%EB%8B%B5%EB%B3%80%202%0A%20%20else%20%EA%B1%B4%EB%84%88%EB%9C%80%0A%20%20%20%20U-%3E%3EW%3A%20%22%EC%9D%B4%20%EC%A7%88%EB%AC%B8%EC%9D%80%20%EA%B1%B4%EB%84%88%EB%9B%B8%EA%B2%8C%EC%9A%94%22%0A%20%20end%0A%20%20W-%3E%3EQ%3A%20buildDraftContent(%5B%EB%8B%B5%EB%B3%80%201%2C%20%EB%8B%B5%EB%B3%80%202%5D)%0A%20%20U-%3E%3EW%3A%20%EC%A0%9C%EB%AA%A9%20%EC%9E%85%EB%A0%A5%2C%20%EB%82%B4%EC%9A%A9%20%EC%88%98%EC%A0%95%2C%20%EA%B3%B5%EA%B0%9C%20%EB%B2%94%EC%9C%84%20%EC%84%A0%ED%83%9D%0A%20%20W-%3E%3EF%3A%20createGratitude%20(%EC%A7%81%EC%A0%91%20%EC%9E%91%EC%84%B1%EA%B3%BC%20%EA%B0%99%EC%9D%80%20%EA%B2%BD%EB%A1%9C)%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<ol><li><strong>첫 번째 질문</strong> — 첫 질문 풀에서 무작위로 하나를 보여 줍니다. 질문을 불러오는 동안은 자리 표시만 보입니다. 답을 써야 다음으로 넘어갑니다.</li><li><strong>두 번째 질문</strong> — 이어지는 질문 풀에서 하나를 보여 줍니다. 답하거나 &quot;이 질문은 건너뛸게요&quot;로 바로 초안을 만들 수 있습니다.</li><li><strong>초안</strong> — 답변을 빈 줄로 이어 붙여 내용에 넣고, 제목은 비워 둡니다.</li><li><strong>저장</strong> — 제목과 내용이 모두 있어야 저장 버튼이 켜집니다. 공개 범위는 기본이 &quot;나만 보기&quot;이고(버튼 &quot;저장하기&quot;), &quot;Circle에 공유&quot;를 고르면 Circle을 골라야 저장할 수 있습니다(버튼 &quot;Circle에 공유하기&quot;). → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a></li></ol><p>질문 카드의 &quot;다른 질문&quot;을 누르면 같은 풀에서 지금 질문과 다른 질문으로 바꿉니다. 사용자가 제안해 선정된 질문에는 &quot;💡 홍길동 #1234님의 질문&quot;처럼 제안자의 공개 이름이 함께 보입니다(기본 질문이나 이름이 없는 질문은 표시하지 않음). → <a href="/grato-docs/features/questions#credit">제안자 표시</a></p><p>질문 화면 아래의 &quot;좋은 질문이 떠올랐나요? 질문 제안하기&quot;로 질문을 제안할 수 있습니다. → <a href="/grato-docs/features/questions">질문 제안과 선정</a></p><h2 id="pools" tabindex="-1">질문 풀 <a class="header-anchor" href="#pools" aria-label="Permalink to &quot;질문 풀 {#pools}&quot;">​</a></h2><p>질문은 <strong>운영자가 선정한 질문</strong>에서 고르고, 그것을 읽지 못하면 앱에 들어 있는 기본 질문 목록으로 대신합니다.</p><table tabindex="0"><thead><tr><th>출처</th><th>위치</th><th>설명</th></tr></thead><tbody><tr><td>선정된 질문</td><td><code>questions</code> (<code>status == &quot;approved&quot;</code>)</td><td>기본 질문(<code>source: &quot;system&quot;</code>) + 사용자가 제안해 선정된 질문(<code>source: &quot;user&quot;</code>)</td></tr><tr><td>앱 안의 기본 질문</td><td><code>src/content/questions.json</code></td><td><code>{ &quot;opening&quot;: [30개], &quot;followup&quot;: [10개] }</code>. <code>seedQuestions</code> 스크립트가 같은 파일을 Firestore의 <code>system_*</code> 문서로 넣음</td></tr></tbody></table><p><code>src/lib/questionApi.js</code>의 <code>loadQuestionPools()</code>가 풀을 만듭니다.</p><ul><li>선정된 질문을 <strong>세션에 한 번</strong> 읽습니다(<code>where(&#39;status&#39;, &#39;==&#39;, &#39;approved&#39;)</code>, 최대 500개, 정렬 없음). 그래서 새로 선정된 질문은 다음에 앱을 열 때부터 나옵니다.</li><li>읽기에 실패했거나 오프라인 캐시에서 온 결과는 저장하지 않아 다음에 다시 읽습니다. 4초 안에 오지 않으면 앱 안의 목록으로 먼저 시작합니다.</li><li><code>buildQuestionPools()</code>가 종류(<code>kind</code>)별로 나눕니다. 어떤 종류에 선정된 <strong>기본</strong> 질문이 하나도 없으면(시드 전, 읽기 실패) <code>questions.json</code>의 목록에 선정된 사용자 질문을 더해 씁니다. 사용자 질문 몇 개가 기본 질문 전체를 대신하지 않게 하기 위해서입니다.</li><li>같은 문구(공백·구두점·보이지 않는 문자를 빼고 같은 것)는 한 번만 넣습니다.</li><li>숨긴 질문(<code>hidden</code>)은 풀에 들어가지 않습니다.</li></ul><p><code>src/content/questions.js</code>는 JSON을 import할 뿐 React·Firebase를 import하지 않는 순수 모듈이라 <code>node:test</code>로 바로 테스트합니다(<code>questions.test.js</code>).</p><table tabindex="0"><thead><tr><th>함수</th><th>동작</th></tr></thead><tbody><tr><td><code>buildQuestionPools(approved)</code></td><td>선정된 질문을 <code>{ opening, followup }</code>으로 나눔 (위의 대체 규칙 포함)</td></tr><tr><td><code>pickQuestion(pool, exclude?)</code></td><td>풀에서 무작위로 하나. <code>exclude</code>(지금 보이는 질문)는 다른 선택지가 있으면 고르지 않음</td></tr><tr><td><code>buildDraftContent(answers)</code></td><td>답변의 앞뒤 공백을 지우고, 빈 답변을 빼고, 빈 줄(<code>\\n\\n</code>)로 이어 붙임</td></tr><tr><td><code>questionCredit(question)</code></td><td>사용자 질문의 &quot;💡 {이름}님의 질문&quot; 문구</td></tr><tr><td><code>normalizeQuestionText</code>, <code>questionTextError</code></td><td>서버와 같은 정규화와 5~80자 확인 (질문 제안·운영자 수정에 사용)</td></tr><tr><td><code>QUESTION_POOL</code>, <code>FOLLOWUP_POOL</code></td><td><code>questions.json</code>의 <code>opening</code>, <code>followup</code> (따로 복사해 두지 않음)</td></tr></tbody></table><p>기본 질문을 추가·수정할 때는 <code>questions.json</code>을 고치고, 배포 때 <code>seedQuestions</code>를 실행합니다. 이어지는 질문은 첫 질문과 상관없이 고르므로 어떤 첫 질문 뒤에 와도 자연스러운 문장으로 씁니다. → <a href="/grato-docs/features/questions#system-questions">기본 질문</a></p><h2 id="길이-제한" tabindex="-1">길이 제한 <a class="header-anchor" href="#길이-제한" aria-label="Permalink to &quot;길이 제한&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>제한</th></tr></thead><tbody><tr><td>답변 하나</td><td>1000자 (두 답변과 빈 줄을 합쳐도 내용 한도 안)</td></tr><tr><td>제목</td><td>1~100자 (화면에서 필수, 규칙은 0~100자)</td></tr><tr><td>내용</td><td>1~3000자</td></tr></tbody></table><h2 id="분석-이벤트" tabindex="-1">분석 이벤트 <a class="header-anchor" href="#분석-이벤트" aria-label="Permalink to &quot;분석 이벤트&quot;">​</a></h2><table tabindex="0"><thead><tr><th>이벤트</th><th><code>props</code></th></tr></thead><tbody><tr><td><code>gratitude_started</code></td><td><code>{ mode: &#39;guided&#39; }</code> (직접 작성은 <code>&#39;manual&#39;</code>)</td></tr><tr><td><code>gratitude_created</code></td><td><code>{ mode: &#39;guided&#39;, hasGroup }</code></td></tr><tr><td><code>question_submitted</code></td><td><code>{ kind }</code> — 질문 제안 성공</td></tr></tbody></table><h2 id="화면-문구" tabindex="-1">화면 문구 <a class="header-anchor" href="#화면-문구" aria-label="Permalink to &quot;화면 문구&quot;">​</a></h2><p>질문으로 쓰기의 문구는 &quot;질문&quot;, &quot;답변&quot;, &quot;초안&quot;으로 기능을 설명합니다. 사용자에게 보이는 문구에는 &quot;AI&quot;나 &quot;인공지능&quot;이라는 표현을 쓰지 않습니다.</p>',17))])}const _=r(E,[["render",A]]);export{b as __pageData,_ as default};
